public static long compressTimeBucket(long timeBucket, int dayStep) {

    if (dayStep < 0) {
        throw new IllegalArgumentException("The dayStep must be positive!");
    }

    if (timeBucket <= 0) {
        return timeBucket;
    }

    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    long extraDays = (day - 1) / dayStep * dayStep;
    long newDate = year * 10000 + month * 100 + (day - extraDays);
    return newDate;
}

