    // Traverse the tree and find the paths of the nodes to remove
    TreePath path = new TreePath(tree.getRootElement().getPath());
    Enumeration<?> elements = tree.getRootElement().children();
    while (elements.hasMoreElements()) {
        DefaultMutableTreeNode element = (DefaultMutableTreeNode) elements.nextElement();
        TreePath currentPath = path.pathByAddingChild(element);
        if (isUnusedNode(element)) {
            nodesToRemove.add(currentPath.toString());
        }
    }

    // Remove the nodes from the tree
    for (String node : nodesToRemove) {
        tree.removeNode(node);
    }

    return nodesToRemove.size();
}

private boolean isUnusedNode(DefaultMutableTreeNode element) {
    // Check if the node has any children
    if (element.getChildCount() > 0) {
        return false;
    }

    // Check if the node has any references
    if (element.getUserObject() != null && element.getUserObject() instanceof TreeReference) {
        TreeReference ref = (TreeReference) element.getUserObject();
        if (ref.hasReferences()) {
            return false;
        }
    }

    // Check if the node has any listeners
    if (element.hasListeners()) {
        return false;
    }

    return true;
}

