        return 0;
    }

    // Remove unused nodes from the category tree
    int removedNodes = 0;
    for (CategoryNode node : this.getUnusedNodes()) {
        this.getRootNode().removeNode(node);
        removedNodes++;
    }

    // Update the model
    this.updateModel();

    return removedNodes;
