protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    Objects.requireNonNull(tour);
    Objects.requireNonNull(graph);
    List<E> edgeList = new ArrayList<>(tour);
    int size = edgeList.size();
    if(size == 0) {
        return null;
    }
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    V endVertex = graph.getEdgeTarget(edgeList.get(size-1));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);
    for(int i=0;i<size-1;i++){
        E edge = edgeList.get(i);
        if(edgeList.get(i+1) != endVertex) {
            vertexList.add(graph.getEdgeSource(edgeList.get(i+1)));
        }
    }
    vertexList.add(endVertex);
    return new GraphPathImpl<V,E>(graph,startVertex,vertexList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    /*
    * Step 1: Initialize the graph path with the edges in the tour
    * Step 2: Sort the edges in the path in ascending order based on their weights
    * Step 3: Create a cursor to traverse the edges in the path
    * Step 4: Iterate through the edges in the path, adding each edge to the graph path
    * Step 5: Return the graph path
    */

    GraphPath<V,E> graphPath = new GraphPath<>();
    List<E> edges = new ArrayList<>(tour);
    edges.sort((e1, e2) -> Double.compare(graph.getEdgeWeight(e1), graph.getEdgeWeight(e2)));
    ListIterator<E> cursor = edges.listIterator();

    while (cursor.hasNext()) {
        E edge = cursor.next();
        graphPath.addEdge(edge);
    }

    return graphPath;
}

