public class CharUtils {

    /**
     * Cache of char results for ASCII characters 0 - 127, see {@link #toCharacterObject}.
     * {@link Character#MAX_VALUE} is 65535, i.e. 16 bit.
     */
    private static final Character[] chars = new Character[128];

    /**
     * <p>Converts the character to a Character.</p>
     *
     * <p>For ASCII 7 bit characters, this uses a cache that will return the same Character object each time.</p>
     *
     * <pre>
     * CharUtils.toCharacterObject(' ')  = ' '
     * CharUtils.toCharacterObject('A')  = 'A'
     * </pre>
     *
     * @param ch the character to convert
     * @return a Character of the specified character
     */
    public static Character toCharacterObject(final char ch) {
        if (ch < 128) {
            synchronized (chars) {
                if (chars[ch] == null) {
                    chars[ch] = Character.valueOf(ch);
                }
                return chars[ch];
            }
        }
        return Character.valueOf(ch);
    }
}

