/**
 * Matches the directories in the full path and the relative path.
 * @param fullPathDirectories the list of directories in the full path
 * @param relativePathDirectories the list of directories in the relative path
 * @return a list of the matched directories, including any leading and trailing separators
 */
private static List<String> matchPathLists(List<String> fullPathDirectories, List<String> relativePathDirectories) {
    // Iterate over the full path directories
    for (int i = 0; i < fullPathDirectories.size(); i++) {
        // Get the current full path directory
        String fullPathDirectory = fullPathDirectories.get(i);
        // Iterate over the relative path directories
        for (int j = 0; j < relativePathDirectories.size(); j++) {
            // Get the current relative path directory
            String relativePathDirectory = relativePathDirectories.get(j);
            // Check if the full path directory matches the relative path directory
            if (fullPathDirectory.equals(relativePathDirectory)) {
                // Return the matched directories, including any leading and trailing separators
                return fullPathDirectories.subList(0, i + 1);
            }
        }
    }
    // If no match was found, return an empty list
    return new ArrayList<>();
}

